from math import *
def f(x):
    return 1-sin(x)
def pt_fixe():
    i=0
    va=1
    test = True
    while test:
        i=i+1
        vp=va
        va=f(va)
        if (abs(va-vp)<=eps):
            test = False
    print("La point fixe est: ",va," apres ",i," iteration")
eps=float(input("Donner eps: "))
pt_fixe()

